"""Record inspected preprint version without assuming journal content equivalence."""
import json,re,subprocess
import ledger as L
from review_batch_0001 import evidence

def main():
 base=L.ROOT/'assets/research-20261105';key='arxiv:1111.7130v2';journal='10.1209/0295-5075/100/28006';rid='arbona-preprint-20261105'
 ev=evidence(base/'arbona-arxiv-1111.7130.pdf','https://arxiv.org/pdf/1111.7130','PDF version header; pp2–5 small structures; pp12–14 large origami variants and redesign; p19 references')
 meta=evidence(base/'arbona-arxiv-1111.7130.html','https://arxiv.org/abs/1111.7130','Title and submission history: v1 2011-11-30, v2 2012-10-02')
 q=['Inspect complete Fig7/Fig9 routing and sequence sources for O1–O6, preserving small64nt test constructs separately.','Acquire journal report and reconcile its relationship to this separately titled preprint; no equivalence or work-key merge yet.','Inspect v1 separately; do not backdate v2 design/source contents to initial2011 submission.']
 p=dict(registry_key=key,registry_id=None,doi=None,title='Cooperativity in the annealing of DNA origamis',authors=['Jean-Michel Arbona','Jean-Pierre Aimé','Juan Elezgaray'],canonical_work_id='work:'+key,canonical_work_status='provisional_unreconciled',publication_type=['preprint'],date_evidence={'date':'2012-10-02','source':meta,'primary_verified':True,'meaning':'Inspected arXiv version2 posting; initial submission2011-11-30 separately retained'},version_links=[],legacy_record={},review_stage='fulltext_reviewed',relevance='design_bearing',design_contributions=['reused_design','modified_design'],catalog_eligibility='unresolved',evidence=[ev,meta],rationale='Preprint Methods/Results report UV annealing/melting tests of O1 Rothemund rectangle, O2 holed rectangle, O3 merged-staple variant and O4 ssDNA-bridge variant. O4 cyclic-register changes are modeled; O5/O6 alter crossover spacing and staple segmentation. These are distinct from64nt scaffold/two32nt staple model constructs.',unresolved_questions=q,reviewer='Codex primary preprint sections',access='partial',run_id=rid,date=L.DATE)
 L.upsert('publication_reviews',p,'Retain independently inspected preprint version with precise dates')
 d=dict(design_id='RDE0011',publication_keys=[key],named_objects=['O1 rectangle','O2 holed rectangle','O3 merged-staple rectangle','O4 ssDNA-bridge rectangle','O5 crossover redesign','O6 crossover redesign'],core_variant_composition='O1/O2 use8-16-8 staples; O3 merges staples in four areas into8-16-16-16-8 patterns; O4 has100nt scaffold bridge. O5 uses13-27-14 segmentation; O6 uses13-14. O4 register permutation series is computational and not a single sequence set.',lattice_decision='unresolved',catalog_eligibility='unresolved',source_completeness='not_verified',source_files=[ev],evidence=[ev],outstanding_checks=q,relationships=[],variant_links=[],legacy_record={},review_run=rid,date=L.DATE)
 old=next((d for d in L.read('design_evidence') if d['design_id']=='RDE0011'),None);assert old is None or old['publication_keys']==[key]
 L.upsert('design_evidence',d,'Retain named variant family with topology and sequence checks open')
 je=evidence(base/'arbona-epl-2012-crossref.json','https://api.crossref.org/works/'+journal,'Title/authors and deposited abstract')
 j=next(p for p in L.read('publication_reviews') if p['registry_key']==journal)
 if j['run_id']=='bootstrap-20261105':
  j.update(review_stage='metadata_screened',relevance='uncertain',design_contributions=['uncertain'],catalog_eligibility='unresolved',evidence=[je],rationale='Journal identity and abstract inspected. Direct offprint download returned empty content; a related differently titled preprint was reviewed separately. Journal design details are not inferred from that preprint.',unresolved_questions=q,reviewer='Codex deposited metadata inspection',access='partial',run_id='B0007',date=L.DATE);L.upsert('publication_reviews',j,'Preserve journal content gap rather than transfer preprint review')
 L.upsert('discovery_edges',dict(edge_id='possible_counterpart:'+key+':'+journal,source_key=key,target_key=journal,relation='possible_journal_counterpart',evidence_url=ev['url'],local_file=ev['local_file'],sha256=ev['sha256'],locator='p2 calls short report elsewhere; ref9 Arbona et al. Europh.Lett.(2012) submitted; compare DOI metadata',reconciliation_state='pending_explicit_version_identity',run_id=rid,date=L.DATE),'Keep journal/preprint relation tentative')
 # Every numbered bibliography entry, irrespective of apparent relevance.
 txt=subprocess.run(['pdftotext','-layout',str(base/'arbona-arxiv-1111.7130.pdf'),'-'],capture_output=True,check=True).stdout.decode();pages=txt.split('\f');refs=re.sub(r'(?m)^\s*(?:19|20)\s*$', '', '\n'.join(pages[18:20]));matches=list(re.finditer(r'^\s*\[(\d+)\]\s+',refs,re.M));nums=[]
 for i,m in enumerate(matches):
  num=int(m.group(1));raw=refs[m.end():matches[i+1].start() if i+1<len(matches) else len(refs)].strip();nums.append(num)
  L.upsert('discovery_edges',dict(edge_id='arxiv-ref:'+key+':'+str(num),source_key=key,target_key='unresolved-reference:'+key+':'+str(num),relation='backward_citation',target_metadata={'number':num,'raw_reference':raw},evidence_url=ev['url'],local_file=ev['local_file'],sha256=ev['sha256'],locator='PDF bibliography ref'+str(num),reconciliation_state='pending_identifier_resolution',run_id=rid,date=L.DATE),'Retain all numbered bibliography entries without relevance filter')
 assert nums==list(range(1,28)), nums
 L.upsert('discovery_runs',dict(run_id=rid,route='backward_citations',query_or_seed=key,source_url=ev['url'],date=L.DATE,pagination={'reference_numbers':nums,'pages_inspected':[19,20]},provider_total=None,retrieved_count=len(nums),deduplicated_additions=1,evidence=[ev,meta,je],failures=['Journal offprint direct download empty; web fetch403'],closure_state='exhausted',closure_scope='All27 numbered bibliography entries on PDF pp19–20 only; target screening and broader citation traversal remain open',checkpoint='Inspected reference boundary at p20 and figures beginning p21; page-number-only lines removed. All27 reference numbers present.'),'Save substantive preprint review and uncapped reference leads')
 print(L.validate())
if __name__=='__main__':main()
